WITH "m0" AS ( INSERT INTO "public"."mutation_item" AS "s" ( "id" , "title" ) VALUES ( $1 , $2 ) RETURNING "s" AS "t0" , NULL::tid AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" ) AS "%")) FROM "r0" AS "t0" )
WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "title" = $1 FROM "public"."mutation_item" AS "b0" WHERE "s"."ctid" = "b0"."ctid" AND ( ( true AND ( "s"."id" = $2 ) ) ) RETURNING "s" AS "t0" , "b0"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" ) AS "%")) FROM "r0" AS "t0" )
WITH "m0" AS ( DELETE FROM "public"."mutation_item" AS "s" WHERE ( true AND ( "s"."id" = $1 ) ) RETURNING "s" AS "t0" , "s"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" ) AS "%")) FROM "r0" AS "t0" )
